package dev.DraGonFiirE.littleperformanceimprovements.client.render;
import com.mojang.blaze3d.vertex.*;import com.mojang.blaze3d.systems.RenderSystem;import org.lwjgl.system.MemoryUtil;import org.lwjgl.opengl.GL14C;import org.joml.Matrix4f;import org.joml.Vector3f;
public final class SphereOutlineBatches {
 private static VertexBuffer target;private static int[] starts,counts;private static double[][] bounds;private static double[] center,radius;private static java.nio.IntBuffer first,length;private static final Vector3f camera=new Vector3f();
 public static void clear(){target=null;}
 public static void upload(VertexBuffer buffer,MeshData mesh){target=null;int count=mesh.drawState().vertexCount();boolean sphere=false;Object tool=team.creative.littletiles.client.LittleTilesClient.PREVIEW_RENDERER.tool();for(Class<?> c=tool.getClass();c!=null;c=c.getSuperclass())try{var f=c.getDeclaredField("builtShape");f.setAccessible(true);sphere=f.get(tool) instanceof team.creative.littletiles.common.placement.shape.type.LittleShapeSphere;break;}catch(NoSuchFieldException ignored){}catch(IllegalAccessException e){break;}if(!sphere||count<200000||mesh.drawState().mode()!=VertexFormat.Mode.DEBUG_LINES||mesh.drawState().format().getVertexSize()!=16||mesh.indexBuffer()!=null){buffer.upload(mesh);return;}
 long src=MemoryUtil.memAddress(mesh.vertexBuffer());double[] lo={Double.POSITIVE_INFINITY,Double.POSITIVE_INFINITY,Double.POSITIVE_INFINITY},hi={Double.NEGATIVE_INFINITY,Double.NEGATIVE_INFINITY,Double.NEGATIVE_INFINITY};for(int i=0;i<count;i++)for(int a=0;a<3;a++){float v=MemoryUtil.memGetFloat(src+(long)i*16+a*4);lo[a]=Math.min(lo[a],v);hi[a]=Math.max(hi[a],v);}center=new double[3];radius=new double[3];for(int a=0;a<3;a++){center[a]=(lo[a]+hi[a])*0.5;radius[a]=(hi[a]-lo[a])*0.5-0.5;if(radius[a]<=0){buffer.upload(mesh);return;}}
 // Refuse the proxy if any actual endpoint lies within it.
 for(int i=0;i<count;i++){double norm=0;for(int a=0;a<3;a++){double q=(MemoryUtil.memGetFloat(src+(long)i*16+a*4)-center[a])/radius[a];norm+=q*q;}if(norm<1){buffer.upload(mesh);return;}}
 int[] groups=new int[count/2];counts=new int[4096];bounds=new double[4096][6];for(var b:bounds){java.util.Arrays.fill(b,0,3,Double.POSITIVE_INFINITY);java.util.Arrays.fill(b,3,6,Double.NEGATIVE_INFINITY);}for(int i=0;i<count;i+=2){int key=0;for(int a=0;a<3;a++){double mid=(MemoryUtil.memGetFloat(src+(long)i*16+a*4)+MemoryUtil.memGetFloat(src+(long)(i+1)*16+a*4))*0.5;int cell=Math.max(0,Math.min(15,(int)((mid-lo[a])/(hi[a]-lo[a])*16)));key=key*16+cell;}groups[i/2]=key;counts[key]+=2;for(int a=0;a<3;a++)for(int j=0;j<2;j++){double q=MemoryUtil.memGetFloat(src+(long)(i+j)*16+a*4);bounds[key][a]=Math.min(bounds[key][a],q);bounds[key][a+3]=Math.max(bounds[key][a+3],q);}}
 starts=new int[4096];int sum=0;for(int i=0;i<4096;i++){starts[i]=sum;sum+=counts[i];}int[] cursor=starts.clone();var owner=new ByteBufferBuilder(count*16);MeshData packed=null;try{long dest=owner.reserve(count*16);for(int i=0;i<count;i+=2){int group=groups[i/2],at=cursor[group];cursor[group]+=2;MemoryUtil.memCopy(src+(long)i*16,dest+(long)at*16,32);}packed=new MeshData(owner.build(),mesh.drawState());buffer.upload(packed);target=buffer;if(first==null){first=MemoryUtil.memAllocInt(4096);length=MemoryUtil.memAllocInt(4096);}}finally{if(packed!=null)packed.close();owner.close();}}
 public static void draw(VertexBuffer buffer){if(buffer!=target){buffer.draw();return;}new Matrix4f(RenderSystem.getModelViewMatrix()).invert().transformPosition(camera.set(0,0,0));double cx=(camera.x-center[0])/radius[0],cy=(camera.y-center[1])/radius[1],cz=(camera.z-center[2])/radius[2],c=cx*cx+cy*cy+cz*cz-1;first.clear();length.clear();for(int i=0;i<4096;i++){if(counts[i]==0)continue;boolean hidden=c>0;for(int corner=0;hidden&&corner<8;corner++){var b=bounds[i];double x=(b[(corner&1)==0?0:3]-center[0])/radius[0]-cx,y=(b[(corner&2)==0?1:4]-center[1])/radius[1]-cy,z=(b[(corner&4)==0?2:5]-center[2])/radius[2]-cz;double aa=x*x+y*y+z*z,bb=cx*x+cy*y+cz*z,discriminant=bb*bb-aa*c;hidden=bb<0&&discriminant>0&&(-bb-Math.sqrt(discriminant))/aa<0.99999;}if(!hidden){first.put(starts[i]);length.put(counts[i]);}}first.flip();length.flip();GL14C.glMultiDrawArrays(org.lwjgl.opengl.GL11C.GL_LINES,first,length);}
}
